insert into measure_analyses (id, proposal_id, status, summary, feasibility_status, precision_level, confidence_level, legal_path, legal_constitutional_change_required, legal_eu_change_required, legal_notes, legal_implementation_delay_min_months, legal_implementation_delay_max_months, implementation_existing_administration, implementation_new_recruitment_needed, implementation_notes, beneficiaries_groups, beneficiaries_description, beneficiaries_count_min, beneficiaries_count_central, beneficiaries_count_max, beneficiaries_source_name, beneficiaries_source_url, simulator_measure_id, reviewed_at, reviewed_by, published_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-4'), uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-1'), 'published', 'Les paramètres sont clairement posés par la source : âge légal ramené à 60 ans, 40 annuités pour une carrière complète, pensions portées au niveau du SMIC revalorisé. Le chiffrage disponible émane d''un seul institut et couvre un périmètre plus large que cette proposition : ses composantes sont donc présentées séparément. Aucune source publique identifiée ne chiffre les effets de retour attendus par le candidat (baisse du chômage, hausse des cotisations).', 'faisable_parametres_connus', 'precise', 'moyenne', 'loi_ordinaire', false, false, 'L''âge légal et la durée de cotisation relèvent de la loi ordinaire — la réforme de 2023 a elle-même été portée par une loi de financement rectificative de la sécurité sociale. Aucune révision constitutionnelle ni négociation européenne n''est requise.', 6, 24, 'oui', 'non_documente', 'Les caisses de retraite appliquent déjà des paramètres d''âge et de durée ; leur modification ne suppose pas de nouvelle structure. Le volume de dossiers à traiter augmenterait fortement l''année de la bascule, sans que la source ne documente les moyens correspondants.', '["Actifs proches de l''âge de départ","Carrières longues"]'::jsonb, 'Concerne l''ensemble des actifs du secteur privé et public, avec un effet immédiat pour les générations proches de 60 ans. Aucune source identifiée ne chiffre le nombre exact de personnes concernées année par année.', null, null, null, null, null, 'melenchon-retraite-60', '2026-09-08', 'Équipe éditoriale Poliscope', '2026-09-08') on conflict (id) do nothing;
insert into measure_analyses (id, proposal_id, status, summary, feasibility_status, precision_level, confidence_level, legal_path, legal_constitutional_change_required, legal_eu_change_required, legal_notes, legal_implementation_delay_min_months, legal_implementation_delay_max_months, implementation_existing_administration, implementation_new_recruitment_needed, implementation_notes, beneficiaries_groups, beneficiaries_description, beneficiaries_count_min, beneficiaries_count_central, beneficiaries_count_max, beneficiaries_source_name, beneficiaries_source_url, simulator_measure_id, reviewed_at, reviewed_by, published_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-5'), uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-60'), 'published', 'La mesure combine un âge légal ramené à 62 ans et un départ anticipé à 60 ans pour les carrières commencées tôt. Un institut indépendant en propose un chiffrage détaillé, avec une fourchette large qui traduit l''incertitude sur le nombre de personnes éligibles au départ anticipé. Aucun plan de financement n''est identifié par la source.', 'faisable_parametres_connus', 'partiellement_precis', 'moyenne', 'loi_ordinaire', false, false, 'Comme toute modification de l''âge légal et de la durée de cotisation, la mesure relève de la loi ordinaire ou d''une loi de financement de la sécurité sociale. La source ne précise pas le véhicule législatif retenu.', 6, 24, 'oui', 'non_documente', 'Le dispositif « carrières longues » existe déjà dans le droit en vigueur : son élargissement s''appuierait sur des règles de liquidation connues des caisses, sans création de structure nouvelle documentée.', '["Actifs proches de 62 ans","Personnes ayant commencé à travailler avant 20 ans"]'::jsonb, 'Selon l''institut ayant chiffré la mesure, environ 57 % de la génération 1962 avait validé des trimestres avant 20 ans et relèverait donc du volet « carrières longues ». Cette proportion ne peut pas être convertie en un effectif annuel sans hypothèse supplémentaire, qui n''est pas documentée.', null, null, null, 'Institut Montaigne', 'https://www.institutmontaigne.org/legislatives-2024/rassemblement-national/abroger-la-reforme-des-retraites-et-pour-ceux-ayant-commence-a-travailler-avant-20-ans-partir-a-40-annuites-de-cotisations/', 'lepen-retraite-62', '2026-09-08', 'Équipe éditoriale Poliscope', '2026-09-08') on conflict (id) do nothing;
insert into measure_analyses (id, proposal_id, status, summary, feasibility_status, precision_level, confidence_level, legal_path, legal_constitutional_change_required, legal_eu_change_required, legal_notes, legal_implementation_delay_min_months, legal_implementation_delay_max_months, implementation_existing_administration, implementation_new_recruitment_needed, implementation_notes, beneficiaries_groups, beneficiaries_description, beneficiaries_count_min, beneficiaries_count_central, beneficiaries_count_max, beneficiaries_source_name, beneficiaries_source_url, simulator_measure_id, reviewed_at, reviewed_by, published_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-6'), uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-36'), 'published', 'La cible est claire — 20 % de hausse de la rémunération moyenne sur un quinquennat — et la population concernée est précisément dénombrée par la statistique publique. En revanche, aucun chiffrage indépendant du coût n''a pu être identifié, pas même pour éprouver l''affirmation du candidat selon laquelle la baisse du nombre d''élèves suffirait à financer la mesure sans dégrader les finances publiques. Le coût est donc affiché comme non chiffré plutôt qu''estimé.', 'faisable_sous_conditions', 'partiellement_precis', 'faible', 'loi_finances', false, false, 'La rémunération des enseignants titulaires relève du statut de la fonction publique : une revalorisation générale passe par décret indiciaire, mais son financement suppose une inscription en loi de finances. La source ne détaille ni la ventilation entre point d''indice, primes et heures supplémentaires, ni le calendrier annuel.', 12, 60, 'oui', 'non', 'La mesure porte sur la rémunération d''agents déjà en poste : elle ne suppose ni structure nouvelle, ni recrutement. Le candidat mentionne en revanche de « nouvelles conditions professionnelles » en contrepartie, sans que leur contenu soit précisé.', '["Enseignants du public","Enseignants du privé sous contrat"]'::jsonb, 'L''ensemble des enseignants de l''enseignement scolaire. La source ne précise pas si le privé sous contrat, dont les maîtres sont rémunérés par l''État, est inclus dans le périmètre.', 712800, 852800, 852800, 'DEPP — L''éducation nationale en chiffres, édition 2025', 'https://www.education.gouv.fr/sites/default/files/2025-08/l-ducation-nationale-en-chiffres-dition-2025-441804.pdf', 'philippe-enseignants', '2026-09-08', 'Équipe éditoriale Poliscope', '2026-09-08') on conflict (id) do nothing;
insert into measure_budget_estimates (id, measure_analysis_id, source_type, source_name, source_url, annual_cost_min, annual_cost_central, annual_cost_max, annual_revenue_min, annual_revenue_central, annual_revenue_max, currency, reference_year, financing_identified, notes) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_budget_estimate:measure-analysis-4-budget-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-4'), 'independent_body', 'Institut Montaigne — composante « retour à l''âge de 60 ans »', 'https://www.institutmontaigne.org/legislatives-2024/nouveau-front-populaire/abroger-la-reforme-des-retraites-restaurer-la-retraite-a-60-ans-en-prenant-en-compte-le-rsa-en-portant-le-minimum-contributif-au-smic/', null, 27, null, null, null, null, 'Md€', 2027, 'non', 'Composante isolée par l''institut au sein d''un chiffrage plus large : le retour à 60 ans (annulation de la réforme de 2010) est évalué à 27 Md€, l''abrogation de la réforme de 2023 à 8,2 Md€ supplémentaires. C''est la ligne qui correspond le plus directement à cette proposition.') on conflict (id) do nothing;
insert into measure_budget_estimates (id, measure_analysis_id, source_type, source_name, source_url, annual_cost_min, annual_cost_central, annual_cost_max, annual_revenue_min, annual_revenue_central, annual_revenue_max, currency, reference_year, financing_identified, notes) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_budget_estimate:measure-analysis-4-budget-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-4'), 'independent_body', 'Institut Montaigne — ensemble du volet retraites chiffré', 'https://www.institutmontaigne.org/legislatives-2024/nouveau-front-populaire/abroger-la-reforme-des-retraites-restaurer-la-retraite-a-60-ans-en-prenant-en-compte-le-rsa-en-portant-le-minimum-contributif-au-smic/', 49, 58, 67, null, null, null, 'Md€', 2027, 'non', 'Périmètre plus large que cette proposition : au retour à 60 ans et à l''abrogation de 2023 s''ajoutent la revalorisation du minimum contributif au SMIC (13,9 Md€), celle du minimum vieillesse (0,7 Md€) et la prise en compte des années de RSA (8,4 Md€). La fourchette reflète une marge de ±15 % appliquée par l''institut. Chiffrage limité au régime de retraite, sans les autres effets sur les finances sociales.') on conflict (id) do nothing;
insert into measure_budget_estimates (id, measure_analysis_id, source_type, source_name, source_url, annual_cost_min, annual_cost_central, annual_cost_max, annual_revenue_min, annual_revenue_central, annual_revenue_max, currency, reference_year, financing_identified, notes) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_budget_estimate:measure-analysis-5-budget-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-5'), 'independent_body', 'Institut Montaigne', 'https://www.institutmontaigne.org/legislatives-2024/rassemblement-national/abroger-la-reforme-des-retraites-et-pour-ceux-ayant-commence-a-travailler-avant-20-ans-partir-a-40-annuites-de-cotisations/', 31.5, 34.7, 44.7, null, null, null, 'Md€', 2027, 'non', 'Chiffrage portant sur l''abrogation de la réforme de 2023 et le retour partiel sur les réformes de 2003 à 2014. L''ampleur de la fourchette tient à la part de la population éligible au départ anticipé : l''institut retient environ 57 % de la génération 1962 ayant validé des trimestres avant 20 ans.') on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-4-assumption-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-4'), 'Âge légal de départ visé', '60', 'ans', 'candidate', 'Âge annoncé par le programme pour une carrière complète de 40 annuités.', 'Programme « L''Avenir en commun » 2025 — chapitre 8', 'https://melenchon2027.fr/programme2025/livre/chapitre8/s8/') on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-4-assumption-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-4'), 'Durée de cotisation pour une carrière complète', '40', 'annuités', 'candidate', 'Durée annoncée par le programme, contre 43 annuités dans le droit en vigueur.', 'Programme « L''Avenir en commun » 2025 — chapitre 8', 'https://melenchon2027.fr/programme2025/livre/chapitre8/s8/') on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-4-assumption-3'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-4'), 'Délai de mise en œuvre législative', '6 à 24', 'mois', 'manual_assumption', 'Estimation Poliscope : une réforme paramétrique des retraites suppose un vote puis une adaptation des systèmes de liquidation des caisses, sans que la source ne fixe de calendrier.', null, null) on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-5-assumption-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-5'), 'Âge légal de départ visé', '62', 'ans', 'candidate', 'Âge réaffirmé par la candidate, avec un départ à 60 ans pour les carrières longues.', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/au-rn-la-reforme-des-retraites-divise-jordan-bardella-et-marine-le-pen-sur-le-programme-pour-la-presidentielle-2027') on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-5-assumption-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-5'), 'Part de la génération concernée par le départ anticipé', '57', '%', 'external_study', 'Proportion de la génération 1962 ayant validé des trimestres avant 20 ans, retenue par l''institut pour expliquer le coût de la mesure.', 'Institut Montaigne', 'https://www.institutmontaigne.org/legislatives-2024/rassemblement-national/abroger-la-reforme-des-retraites-et-pour-ceux-ayant-commence-a-travailler-avant-20-ans-partir-a-40-annuites-de-cotisations/') on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-6-assumption-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-6'), 'Hausse visée de la rémunération moyenne', '20', '%', 'candidate', 'Objectif annoncé sur un quinquennat, présenté comme devant porter les salaires au moins au niveau de la moyenne européenne, en particulier en milieu de carrière.', 'franceinfo', 'https://www.franceinfo.fr/elections/presidentielle/presidentielle-2027-le-candidat-horizons-edouard-philippe-veut-augmenter-de-20-la-remuneration-moyenne-des-enseignants-sur-un-quinquennat_8159927.html') on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-6-assumption-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-6'), 'Enseignants de l''enseignement scolaire', '852 800', 'personnes', 'official', 'Dont 712 800 dans le public et 140 000 dans le privé sous contrat, à la rentrée 2024. La borne basse retenue pour les bénéficiaires correspond au seul secteur public, périmètre non tranché par la source.', 'DEPP — L''éducation nationale en chiffres, édition 2025', 'https://www.education.gouv.fr/sites/default/files/2025-08/l-ducation-nationale-en-chiffres-dition-2025-441804.pdf') on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-6-assumption-3'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-6'), 'Financement par la baisse démographique', 'non vérifié', null, 'candidate', 'Le candidat affirme que la baisse du nombre d''élèves dégage les marges nécessaires. Aucune source indépendante identifiée ne confronte ce montant à celui de la revalorisation : l''affirmation est rapportée, pas validée.', 'franceinfo', 'https://www.franceinfo.fr/elections/presidentielle/presidentielle-2027-le-candidat-horizons-edouard-philippe-veut-augmenter-de-20-la-remuneration-moyenne-des-enseignants-sur-un-quinquennat_8159927.html') on conflict (id) do nothing;
